CREATE TABLE products (
  product_id   NUMBER        PRIMARY KEY,
  product_name VARCHAR2(50)  NOT NULL,
  price        NUMBER(10,2)  NOT NULL,
  status       VARCHAR2(15)  DEFAULT 'ACTIVE' NOT NULL
);

CREATE TABLE product_feed (
  product_id   NUMBER,
  product_name VARCHAR2(50),
  price        NUMBER(10,2),
  discontinued CHAR(1)
);

INSERT INTO products VALUES (1, 'USB-C Cable',    299,  'ACTIVE');
INSERT INTO products VALUES (2, 'Wireless Mouse', 799,  'ACTIVE');
INSERT INTO products VALUES (3, 'Laptop Stand',   1499, 'ACTIVE');

INSERT INTO product_feed VALUES (2, 'Wireless Mouse', 749,  'N');
INSERT INTO product_feed VALUES (3, 'Laptop Stand',   1499, 'Y');
INSERT INTO product_feed VALUES (4, 'Webcam HD',      2499, 'N');
INSERT INTO product_feed VALUES (5, 'Old Keyboard',   999,  'Y');

COMMIT;

MERGE INTO products p
USING product_feed f
ON (p.product_id = f.product_id)
WHEN NOT MATCHED THEN
  INSERT (product_id, product_name, price)
  VALUES (f.product_id, f.product_name, f.price);

SELECT product_id, product_name, price FROM products ORDER BY product_id;

ROLLBACK;

INSERT INTO product_feed VALUES (2, 'Wireless Mouse', 699, 'N');

MERGE INTO products p
USING product_feed f
ON (p.product_id = f.product_id)
WHEN MATCHED THEN
  UPDATE SET p.price = f.price;
